import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/27-Who-knows-you-best-Recommended.html","title":"27-谁在了解你？——推荐算法的秘密","lang":"zh-CN","frontmatter":{"title":"27-谁在了解你？——推荐算法的秘密","icon":"read","date":"2025-04-25T07:03:38.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":18,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"efcdc102184fcc5dac2e60c9d14b000ad7f7a65e","time":1745562517000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"初始化"},{"hash":"40cef953d791bbdd75178699819ed1405a318259","time":1745562191000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"e7262a330c91fdd3b41bf50a2b3031aeee89e2e3","time":1745560394000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"bc6288cae4d6037afd4d32ad7a32235c4ffe9620","time":1745559821000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"897f3e82a6971b4c67495ddafe0fef7875fb8df2","time":1745558670000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"22513a267bc9c291dfe5fcc208e0800157122c54","time":1745544845000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"19ab7f6a4a8c0b0bc61ef4248c24b7c6750c47ef","time":1745536598000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add new article \\"27-谁是最了解你的人：推荐\\" to Programming-thinking section"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":10.77,"words":3232},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/27-Who-knows-you-best-Recommended.md"}`),a={name:`27-Who-knows-you-best-Recommended.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/raw-20250425105601326-Cv_rrqiw.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>在前面学习了搜索引擎，我们聊的是“搜索”——你主动出发，像个小侦探一样去找线索。而今天我们要说的是“推荐”——你啥也没干，结果消息自己敲门进来了。</p><p>其实现在的推荐算法几乎是无处不在了，你有没有发现这种事儿经常发生？比如你刚刚搜了一下猫咪打喷嚏的视频，下一秒，视频平台立刻给你端上一堆更萌的猫猫合集。又或者你爸妈买了双跑鞋，购物网站马上推送一大堆运动服和智能手环。没错，你还没说“我想要”，它就已经猜到你心里去了。</p><p>是不是哪里有一双眼睛一直在看着我们，偷窥我们内心的小秘密？这背后的魔法师，就是我们今天的主角：<strong>推荐算法</strong>。</p><p>我们一起来看看这双眼睛是如何发挥作用的～</p><h2 id="_1-从书店小弟到推荐天才" tabindex="-1"><a class="header-anchor" href="#_1-从书店小弟到推荐天才"><span>1. 从书店小弟到推荐天才</span></a></h2><p>要说推荐算法，就得从最早的购物网站——<strong>亚马逊</strong>讲起。</p><figure><img src="/assets/image-20250425140312239-siSV_3Ch.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这家巨头在刚起步时，只是个卖书的网站。一开始他们的方式很简单：把书都摆出来，顾客想买啥就自己挑。</p><p>但很快他们意识到：嘿，人们的购买习惯其实有规律可循！如果掌握了这个规律，就可以卖出更多的书。什么规律呢？</p><p>这个规律，其实你自己早就掌握了。只是你还未发现，我们来看看例子：</p><figure><img src="/assets/ppppp-LNfFApkm.png" alt="不要插入此图片" tabindex="0" loading="lazy"><figcaption>不要插入此图片</figcaption></figure><p>如果小悦买了《哈利·波特》第一本，在小悦生日的时候，你会买什么书送给小悦？小悦可能对什么感兴趣？——也许是第二册、第三册，甚至是漫画版的《哈利·波特》。</p><p>不仅仅是送生日礼物，就算是推荐给小悦也是再合适不过的。所以，这个不是我教给你的方法，而是你本身就会的方法！（学习就是把某些你潜意识的知识，挖掘出来变成有意识的。）</p><p>亚马逊按上面人类会做的方法，思考着：如果能提前猜到顾客的心思，那销量不就蹭蹭涨了吗？</p><p>不过，你可以靠着经验给小悦选生日礼物、推荐书，但机器可没有经验。它要怎么办呢？亚马逊想了个办法：不靠直觉，而是靠<strong>大数据</strong>。</p><p>什么意思呢？亚马逊公司会把在自己网站上买过《哈利·波特与魔法石》的用户数据收集起来，看看他们后来又买了什么书，然后把这些书放在《哈利·波特与魔法石》的下边，推荐给用户。</p><p>是不是还是想不到，亚马逊的具体操作？别急，我们一起来看看下面的例子：</p><p>他们分析买过《哈利·波特与魔法石》这本书的用户，还买了什么别的书。结果发现：全网站有1000个人买了《哈利·波特与魔法石》，然后经过统计，发现在这1000人里头，有800个人买了哈利·波特系列的第2册，有700个人买了第3册。还有600个人买了《福尔摩斯探案集》，比买哈利·波特第4册的人还多！</p><p>这样一来，亚马逊给用户推荐的时候，就不是按照哈利波特2、3、4这样的顺序推荐了。而是先推荐哈利波特第二、三册，之后推荐《福尔摩斯探案集》。简单直接，但效果惊人。——推荐系统就此诞生！</p><p>这就是早期的推荐算法，虽然技术含量不高，却已经相当聪明了。不过跟今天的推荐算法相比，它还只能算是一道小菜。今天的推荐算法非常庞大且精准，可以为每一个用户建立一个兴趣档案。</p><h2 id="_2-看不见的-标签机" tabindex="-1"><a class="header-anchor" href="#_2-看不见的-标签机"><span>2. 看不见的“标签机”</span></a></h2><figure><img src="/assets/raw-20250425134500208-DWeloM9P.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>不过嘛，今天的推荐算法可不是当年的“老实人”了，它已经变身为超级智能助理。</p><p>它不仅知道你买了啥，还知道你在哪个页面停留了多久，喜欢在晚上几点刷视频，你看完这个视频又看了哪个视频，甚至能猜到你什么时候心情好、什么时候想点外卖，这些信息全都会记录在案。</p><p>每一次点击、滑动、点赞、收藏，都会被记录并转化为一张你的“兴趣画像”。网站就会根据你的记录给你贴上标签，你的标签可能是“猫咪爱好者”、“周五熬夜党”、“动作片迷”、“糖果控”……然后以此标签，为你推荐你可能感兴趣的东西。</p><p>举个例子：网站可能会发现，你到了周五的晚上，就会睡得很晚，而且还喜欢在这个时间看电影。那么，它就会在周五的晚上，等你放了学，就把好多你感兴趣的电影摆在首页，吸引你去点击。它就像一个精明的服务生，早早备好你爱看的内容，恭候大驾。</p><p>有了这么好的推荐算法，你的生活会变得更加方便。推荐算法就像是一个忠诚的<strong>仆人</strong>，老老实实地记录你的爱好，然后推荐你感兴趣的东西，让你过得很舒心。</p><p>通过前面的讲解，你可能觉得这挺好的啊！是的，它确实让生活更轻松了。</p><p>但你有没有想过：这份贴心，也可能是一种“甜蜜的陷阱”。</p><h2 id="_3-地平说-的故事-和茧房的陷阱" tabindex="-1"><a class="header-anchor" href="#_3-地平说-的故事-和茧房的陷阱"><span>3. “地平说”的故事，和茧房的陷阱</span></a></h2><figure><img src="/assets/image-20250425135246343-CwhsVb96.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>咱们来说个真实得让人咋舌的例子：地球到底是圆的，还是平的？</p><p>“这还用问吗？”你可能会笑出声，“当然是圆的！”</p><p>但有些人相信“地平说”，就是认为地球不是个球，而是扁扁的、平平的。注意：我说的这些人可不是古人，而是生活在21世纪的实打实的现代人。</p><p>那你肯定会好奇了，这些人是不是生活在比较落后的地区，没有见过宇宙飞船给地球拍的照片？——还真不是，这些人都可以上网，只要愿意，他们可以看到各种各样的信息。那他们为什么会相信地平说呢？</p><p>问题出在哪儿？</p><p>这里头的原因很复杂，但有些人相信地平说，推荐算法要背一部分锅。在相信地平说的人当中，有一部分人本来是相信<strong>地圆说</strong>的，也认为地球是圆的，他们抱着好奇的心态看了关于地平说的内容。结果呢，推荐算法以为他们喜欢地平说的内容，于是不停给他们推荐这方面的内容。这些人呢，整天都看到地平说的信息，时间长了，难免就被误导了。</p><p>换句话来说：有些人本来只是出于好奇，点开了一个讲“地平说”的视频。结果推荐算法一看：“哟，这位用户对地平说感兴趣啊！”于是开始不断推送相关内容。久而久之，他们看到的都是“地球是平的”论调的信息，听不到其他声音，慢慢地，也就动摇了。</p><p>上面虽然有重复赘述之嫌，但还是希望你能 get 到我要表达的。</p><p>推荐算法这个只会奉承你的仆人，可能会让你只看自己爱看的东西，最后陷进一个<strong>小圈子</strong>里去。如同古代皇帝，如果只听信爱听的太监或奸臣说的，那这个皇帝基本上也就废了。</p><p>虽然你不至于相信地球是平的，但是推荐算法可能会让你接触不到新的信息，沉浸在自己喜欢的那一片小世界里，没办法再继续成长了。</p><p>这个现象，被人们叫作“<strong>信息茧房</strong>”，茧就是毛毛虫吐丝做的那个茧，一层又一层，把自己包住，最终看不见外面的世界。也就是说，如果你只关注自己感兴趣的人和事，那你最后就会像一只毛毛虫一样，用吐出的丝完全把自己包围起来，眼界就完全封闭住了，这就是推荐算法的危险之处。</p><p>写到这，我想起了我许多年前在朋友圈中发布的一段对于推荐算法的观点：人们往往只相信那些他们<strong>亲眼看到的</strong>、<strong>亲身感受到的</strong>、或者早已在脑海中形成印象的东西。他们更愿意接受<strong>已经得到社会认同的观念</strong>，以及那些<strong>与自己世界观相符的解释</strong>。至于那些颠覆认知、挑战信仰、打破舒适圈的信息，哪怕就摆在面前，也往往会被下意识地<strong>忽略、否定，甚至视而不见</strong>。</p><p>而在今天这个由推荐算法主导的信息时代，这种倾向只会变得更加明显。算法会不断记录我们的点击、偏好和停留时间，继而精准地投喂我们想看的内容、认同的观点、熟悉的语气。这些算法就像是一面面“认知回音壁”，把我们已经相信的东西，反复包装、放大、回响。久而久之，我们看到的世界，不再是客观真实的全貌，而是一面经过滤镜处理的镜子——它只映照出我们想看到的那一部分。</p><p>于是，我们就这样陷入一个温柔却危险的信息茧房：越看，越信；越信，越窄。<strong>推荐算法在强化我们的选择的同时，也悄悄关上了通往不同观点与多元认知的大门。</strong></p><h2 id="_4-怎么破茧而出" tabindex="-1"><a class="header-anchor" href="#_4-怎么破茧而出"><span>4. 怎么破茧而出？</span></a></h2><p>那么，我们该如何像蝴蝶一样打破茧房，重新获得自由呢？</p><p>对于平台：为了不让我们变成困在小世界里的毛毛虫，很多平台也想了办法。他们会在你喜欢的内容之间，<strong>夹带一点“随机推荐”</strong>，让你有机会跳出旧圈子，接触新观点。</p><p>不过如果你稍微拥有批判性思维，那我想告诉你：不要等待平台给你的一些些随机来改变自己，跳出圈子。你要自己主动出击，有意识的去改变。毕竟，有些平台虽然明面上说有夹带随机的推荐，不然你成瘾，但实则没有给你随机。因为只有“作茧自缚的你”，才能造就愈发依赖平台的你。<s>这样就会越依赖该平台。</s> 也是因为：人是特别容易沉迷哪些，自己所相信的。</p><p>这对我们生活、学习其实有很深的启发。</p><ul><li>交朋友时，不妨试着去和不太一样的人聊聊天。适当的时候还可以扩大社交圈子，不要仅限于自身的小区或者班级；</li><li>读书的时候，偶尔翻一翻你平时不太感兴趣的那一类书；</li><li>别只看漫画，也看看科幻小说、历史故事；</li><li>别老刷搞笑短视频，也试试纪录片。</li><li>……</li></ul><p>不要一味任由着自己，跟着兴趣爱好走。这样，你的路才有可能越走越宽。</p><p>阅读本书的你，不知道是否偏科或者有你不喜欢学校安排的学科。你有没有想过，学校为什么要设计哪些那么多的课呢？</p><p>其实学校里的那些“你不爱学的课”，其实也是为了帮你打破“知识茧房”而设计的——别只偏爱语文和数学，物理、生物、地理……都值得你张开眼界去看看。</p><p>或许有些知识可能比较枯燥，但是它们可以拓宽你的眼界，是你未来获取自由的保证，可不能偏科呢！</p><h2 id="_5-小结-推荐算法-不只是算法" tabindex="-1"><a class="header-anchor" href="#_5-小结-推荐算法-不只是算法"><span>5. 小结：推荐算法，不只是算法</span></a></h2><p>你看，推荐算法不只是一个冷冰冰的程序，而是与你生活紧密相关的一套机制。它会迎合你的口味，也可能误导你的判断。它能帮你省力，也可能让你封闭。</p><p>而理解推荐算法，其实是我们接下来的学习旅程中，理解人工智能的第一步！</p><p>因为——推荐算法，就是人工智能技术的早期代表之一。</p>`,60)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};